package net.officefloor.hq.app.sheet;

import jakarta.validation.Valid;
import jakarta.validation.constraints.NotBlank;
import jakarta.validation.constraints.NotNull;
import jakarta.validation.constraints.Pattern;
import jakarta.validation.constraints.Size;
import java.time.LocalDate;
import net.officefloor.hq.app.session.SessionController;
import org.springframework.validation.annotation.Validated;
import org.springframework.web.bind.annotation.PathVariable;
import org.springframework.web.bind.annotation.PutMapping;
import org.springframework.web.bind.annotation.RequestBody;
import org.springframework.web.bind.annotation.RequestMapping;
import org.springframework.web.bind.annotation.RestController;
import org.springframework.web.bind.annotation.SessionAttribute;

@RestController
@Validated
@RequestMapping("/api/sheets")
public class SheetController {

    public record SheetView(String id, LocalDate today) {
        static SheetView of(Sheet sheet) {
            return new SheetView(sheet.getId(), sheet.getToday());
        }
    }

    public record TodayChange(@NotNull LocalDate today) {
    }

    private final SheetService service;

    public SheetController(SheetService service) {
        this.service = service;
    }

    /** Load a sheet by id, starting it empty if it was never loaded before. */
    @PutMapping("/{id}")
    public SheetView load(@PathVariable @NotBlank @Size(max = 100) @Pattern(regexp = "[A-Za-z0-9_.-]+") String id) {
        return SheetView.of(service.load(id));
    }

    /** Change the sheet's today. */
    @PutMapping("/{id}/today")
    public SheetView setToday(@PathVariable @NotBlank @Size(max = 100) @Pattern(regexp = "[A-Za-z0-9_.-]+") String id,
            @Valid @RequestBody TodayChange change, @SessionAttribute(SessionController.USER) String user) {
        return SheetView.of(service.setToday(user, id, change.today()));
    }
}
package net.officefloor.hq.app.sheet;

import jakarta.persistence.Column;
import jakarta.persistence.Entity;
import jakarta.persistence.Id;
import jakarta.persistence.Table;
import java.time.Instant;
import java.time.LocalDate;

/** A sheet, chosen by its id. Everything else in the app is kept per sheet. */
@Entity
@Table(name = "sheet")
public class Sheet {

    @Id
    private String id;

    @Column(name = "created_at", nullable = false)
    private Instant createdAt;

    /** The sheet's own today: date decisions and default dates use it, never the real clock. */
    @Column(name = "today", nullable = false)
    private LocalDate today;

    protected Sheet() {
    }

    public Sheet(String id) {
        this.id = id;
        this.createdAt = Instant.now();
        this.today = LocalDate.now();
    }

    public String getId() {
        return id;
    }

    public Instant getCreatedAt() {
        return createdAt;
    }

    public LocalDate getToday() {
        return today;
    }

    public void setToday(LocalDate today) {
        this.today = today;
    }
}
package net.officefloor.hq.app.sheet;

import jakarta.persistence.LockModeType;
import java.util.Optional;
import org.springframework.data.jpa.repository.JpaRepository;
import org.springframework.data.jpa.repository.Lock;
import org.springframework.data.jpa.repository.Modifying;
import org.springframework.data.jpa.repository.Query;
import org.springframework.data.repository.query.Param;

public interface SheetRepository extends JpaRepository<Sheet, String> {

    /** The sheet, locked until the transaction ends. */
    @Lock(LockModeType.PESSIMISTIC_WRITE)
    Optional<Sheet> findWithLockById(String id);

    /** Moves the sheet's last claim number on by one; the row stays locked until the transaction ends. */
    @Modifying(flushAutomatically = true)
    @Query(value = "UPDATE sheet SET last_claim_number = last_claim_number + 1 WHERE id = :id", nativeQuery = true)
    int incrementClaimNumber(@Param("id") String id);

    @Query(value = "SELECT last_claim_number FROM sheet WHERE id = :id", nativeQuery = true)
    long lastClaimNumber(@Param("id") String id);
}
package net.officefloor.hq.app.sheet;

import java.time.LocalDate;
import net.officefloor.hq.app.rollup.RollupService;
import org.springframework.dao.DataIntegrityViolationException;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;

/** Loads a sheet by id; a sheet never loaded before starts empty. */
@Service
public class SheetService {

    private final SheetRepository sheets;
    private final RollupService rollup;

    public SheetService(SheetRepository sheets, RollupService rollup) {
        this.sheets = sheets;
        this.rollup = rollup;
    }

    public Sheet load(String id) {
        return sheets.findById(id).orElseGet(() -> create(id));
    }

    /**
     * Change the sheet's today; every date decision on the sheet follows it. It has no audit line of its own, only
     * the figures it moves.
     */
    @Transactional
    public Sheet setToday(String by, String id, LocalDate today) {
        Sheet sheet = load(id);
        RollupService.Snapshot before = rollup.snapshot(id);
        sheet.setToday(today);
        Sheet saved = sheets.saveAndFlush(sheet);
        rollup.recordChanges(by, id, before);
        return saved;
    }

    /** Loads the sheet and locks it until the transaction ends, so changes checked against the whole sheet run in turn. */
    @Transactional
    public Sheet lock(String id) {
        load(id);
        return sheets.findWithLockById(id).orElseThrow();
    }

    /** Takes the sheet's next claim number; two callers at once never get the same one. */
    @Transactional
    public long nextClaimNumber(String id) {
        load(id);
        sheets.incrementClaimNumber(id);
        return sheets.lastClaimNumber(id);
    }

    private Sheet create(String id) {
        try {
            return sheets.saveAndFlush(new Sheet(id));
        } catch (DataIntegrityViolationException e) {
            // another user created it at the same moment
            return sheets.findById(id).orElseThrow(() -> e);
        }
    }
}
package net.officefloor.hq.app.claim;

import java.math.BigDecimal;
import java.math.RoundingMode;
import java.time.LocalDate;
import java.util.List;
import net.officefloor.hq.app.Audit;
import net.officefloor.hq.app.period.PeriodRepository;
import net.officefloor.hq.app.person.Person;
import net.officefloor.hq.app.person.PersonRepository;
import net.officefloor.hq.app.rate.Rate;
import net.officefloor.hq.app.rate.RateRepository;
import net.officefloor.hq.app.rollup.RollupService;
import net.officefloor.hq.app.sheet.SheetService;
import org.springframework.http.HttpStatus;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;
import org.springframework.web.server.ResponseStatusException;

/** The claims people make on a sheet. */
@Service
public class ClaimService {

    private final ClaimRepository claims;
    private final PersonRepository people;
    private final RateRepository rates;
    private final PeriodRepository periods;
    private final SheetService sheets;
    private final RollupService rollup;
    private final Audit audit;

    public ClaimService(ClaimRepository claims, PersonRepository people, RateRepository rates,
            PeriodRepository periods, SheetService sheets, RollupService rollup, Audit audit) {
        this.claims = claims;
        this.people = people;
        this.rates = rates;
        this.periods = periods;
        this.sheets = sheets;
        this.rollup = rollup;
        this.audit = audit;
    }

    /** All the claims on the sheet, newest first. */
    @Transactional(readOnly = true)
    public List<Claim> list(String sheetId) {
        return claims.findBySheetIdOrderByIdDesc(sheetId);
    }

    /**
     * Adds a claim for the person; a missing date takes the sheet's today. Refused when dated in a closed period or
     * after the person's retirement date.
     */
    @Transactional
    public Claim add(String by, String sheetId, Long personId, BigDecimal amount, LocalDate date, String note) {
        LocalDate on = dateOrToday(sheetId, date);
        refuseInClosedPeriod(sheetId, on);
        RollupService.Snapshot before = rollup.snapshot(sheetId);
        Person person = person(sheetId, personId);
        refuseAfterRetirement(person, on);
        Claim added = claims.saveAndFlush(new Claim(sheetId, personId, scaled(amount), on, noteOf(note)));
        audit.recordOnCommit(record("CLAIM_ADDED", by, person, added));
        rollup.recordChanges(by, sheetId, before);
        return added;
    }

    /**
     * Edits a claim; refused unless it is a draft, when it is dated in a closed period, or when the edit would date
     * it in one. An open claim is changed by voiding it and adding a new one.
     */
    @Transactional
    public Claim update(String by, String sheetId, Long id, BigDecimal amount, LocalDate date, String note) {
        LocalDate on = dateOrToday(sheetId, date);
        Claim claim = claims.findByIdAndSheetId(id, sheetId)
                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such claim."));
        if (claim.getStatus() != ClaimStatus.DRAFT) {
            throw new ResponseStatusException(HttpStatus.CONFLICT, "Only a draft claim can be edited.");
        }
        refuseInClosedPeriod(sheetId, claim.getDate());
        refuseInClosedPeriod(sheetId, on);
        refuseAfterRetirement(person(sheetId, claim.getPersonId()), on);
        RollupService.Snapshot before = rollup.snapshot(sheetId);
        claim.setAmount(scaled(amount));
        claim.setDate(on);
        claim.setNote(noteOf(note));
        Claim saved = claims.saveAndFlush(claim);
        audit.recordOnCommit(record("CLAIM_EDITED", by, person(sheetId, saved.getPersonId()), saved));
        rollup.recordChanges(by, sheetId, before);
        return saved;
    }

    /**
     * Moves the claim to the status; a change its status does not allow is refused, as is settling by the user
     * who opened it and any change to a claim dated in a closed period.
     */
    @Transactional
    public Claim changeStatus(String by, String sheetId, Long id, ClaimStatus next) {
        // the sheet is locked before the claim, in the order a period closing takes them
        sheets.lock(sheetId);
        Claim claim = claims.findWithLockByIdAndSheetId(id, sheetId)
                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such claim."));
        refuseInClosedPeriod(sheetId, claim.getDate());
        RollupService.Snapshot before = rollup.snapshot(sheetId);
        if (!claim.getStatus().canMoveTo(next)) {
            throw new ResponseStatusException(HttpStatus.CONFLICT,
                    "A " + claim.getStatus() + " claim cannot become " + next + ".");
        }
        if (next == ClaimStatus.SETTLED && by.equals(claim.getOpenedBy())) {
            throw new ResponseStatusException(HttpStatus.CONFLICT, "The user who opened a claim cannot settle it.");
        }
        Long number = claim.getNumber();
        claim.setStatus(next);
        if (next == ClaimStatus.OPEN) {
            number = sheets.nextClaimNumber(sheetId);
            claim.setNumber(number);
            claim.setOpenedBy(by);
        }
        Person person = person(sheetId, claim.getPersonId());
        String due = null;
        if (next == ClaimStatus.SETTLED) {
            // the due is fixed at the figure a statement bound it to, else at the rate the person's grade has in
            // force on the claim's date; with none it stays live
            BigDecimal fixed = claim.isStated() && claim.getStatedDue() != null ? claim.getStatedDue()
                    : liveDue(sheetId, person, claim);
            claim.setSettledDue(fixed);
            due = fixed == null ? "n/a" : fixed.toPlainString();
        }
        Claim saved = claims.saveAndFlush(claim);
        String event = switch (next) {
            case OPEN -> "CLAIM_OPENED";
            case SETTLED -> "CLAIM_SETTLED";
            case VOID -> "CLAIM_VOIDED";
            case DRAFT -> throw new IllegalStateException();
        };
        audit.recordOnCommit(record(event, by, person, saved, number) + (due != null ? " due=" + due : ""));
        rollup.recordChanges(by, sheetId, before);
        return saved;
    }

    /** The claim's live due: at the rate its person's grade has in force on its date; null (n/a) with none. */
    public BigDecimal liveDue(String sheetId, Person person, Claim claim) {
        return rates.findInForce(sheetId, person.getGrade(), claim.getDate()).map(Rate::getPct)
                .map(pct -> dueOn(claim.getAmount(), pct)).orElse(null);
    }

    /** The figure the claim shows and totals: its settled due, else the one a statement bound it to, else live. */
    public BigDecimal figure(String sheetId, Person person, Claim claim) {
        if (claim.getSettledDue() != null) {
            return claim.getSettledDue();
        }
        return claim.isStated() ? claim.getStatedDue() : liveDue(sheetId, person, claim);
    }

    /**
     * Refuses a change to a claim dated on the date when a closed period contains it. The sheet stays locked until
     * the transaction ends, so a period closing at the same moment is checked in turn.
     */
    private void refuseInClosedPeriod(String sheetId, LocalDate date) {
        sheets.lock(sheetId);
        if (periods.existsBySheetIdAndClosedTrueAndFromLessThanEqualAndToGreaterThanEqual(sheetId, date, date)) {
            throw new ResponseStatusException(HttpStatus.CONFLICT, "That claim is dated in a closed period.");
        }
    }

    /** Refuses a claim for the person dated after their retirement date; one on or before it is allowed. */
